-- =====================================================================
-- WebiGeeks DIRTY DATASET : raw_enrollments  (308 rows, all TEXT on purpose)
-- Paste this whole block in pgAdmin 4 > Query Tool > press F5 (Execute)
-- =====================================================================
DROP TABLE IF EXISTS raw_enrollments CASCADE;

CREATE TABLE raw_enrollments (
    enrollment_id  TEXT,
    full_name      TEXT,
    gender         TEXT,
    age            TEXT,
    email          TEXT,
    phone          TEXT,
    city           TEXT,
    course         TEXT,
    enroll_date    TEXT,
    fee_paid       TEXT,
    payment_mode   TEXT,
    status         TEXT,
    rating         TEXT
);

